const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative circles on the right
  slide.addShape(pres.shapes.OVAL, {
    x: 7.5, y: -0.5, w: 3.5, h: 3.5,
    fill: { color: theme.secondary, transparency: 75 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.8, y: 2.8, w: 4.0, h: 4.0,
    fill: { color: theme.accent, transparency: 85 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 8.5, y: 3.5, w: 2.0, h: 2.0,
    fill: { color: theme.light, transparency: 80 }
  });

  // Gold accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.3, w: 0.06, h: 2.8,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("State of Developer\nEcosystem 2024", {
    x: 1.0, y: 1.3, w: 6.0, h: 1.8,
    fontSize: 38, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", valign: "top",
    lineSpacingMultiple: 1.1
  });

  // Subtitle
  slide.addText("Language Trends, Satisfaction, and Strategic Shifts", {
    x: 1.0, y: 3.2, w: 6.0, h: 0.5,
    fontSize: 20, fontFace: "Calibri",
    color: theme.accent, align: "left", valign: "top"
  });

  // Survey info
  slide.addText("Based on JetBrains' annual survey of 23,262 developers worldwide", {
    x: 1.0, y: 3.9, w: 6.0, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", align: "left", valign: "top",
    transparency: 30
  });

  // Year badge
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 1.0, y: 4.7, w: 1.2, h: 0.4,
    fill: { color: theme.accent },
    rectRadius: 0.03
  });
  slide.addText("2024", {
    x: 1.0, y: 4.7, w: 1.2, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

