const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 3,
  title: 'Python Is Now the #1 Primary Language at 35%'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.3, y: 0.2, w: 9.4, h: 0.7,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    fit: "shrink"
  });

  // Horizontal bar chart - Primary Language
  const barData = [{
    name: "Primary Language %",
    labels: ["SQL", "TypeScript", "JavaScript", "Java", "Python"],
    values: [17, 19, 28, 30, 35]
  }];

  slide.addChart(pres.charts.BAR, barData, {
    x: 0.3, y: 1.0, w: 5.2, h: 3.8,
    barDir: "bar",
    showTitle: false,
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    chartColors: ["2a9d8f"],
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: "64748B",
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisMinVal: 0,
    valAxisMaxVal: 40,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    plotArea: { fill: { color: "FFFFFF" } }
  });

  // Right side: insight cards
  // Card 1 - Ecosystem Lock-In
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 1.0, w: 3.9, h: 1.3,
    fill: { color: "F0F4F5" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 1.0, w: 0.06, h: 1.3,
    fill: { color: theme.accent }
  });
  slide.addText("Ecosystem Lock-In", {
    x: 6.05, y: 1.05, w: 3.5, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });
  slide.addText("Adoption intent remains below 6%\nacross all languages — developers rarely\nplan to switch their primary stack.", {
    x: 6.05, y: 1.4, w: 3.5, h: 0.85,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, align: "left", valign: "top",
    lineSpacingMultiple: 1.2
  });

  // Card 2 - Adoption Intent comparison
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 2.5, w: 3.9, h: 2.3,
    fill: { color: "F0F4F5" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 2.5, w: 0.06, h: 2.3,
    fill: { color: theme.secondary }
  });
  slide.addText("Adoption Intent vs. Primary Usage", {
    x: 6.05, y: 2.55, w: 3.5, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });

  // Mini comparison bars
  const items = [
    { name: "Python", primary: 35, adopt: 6 },
    { name: "Java", primary: 30, adopt: 4 },
    { name: "JavaScript", primary: 28, adopt: 3 },
    { name: "TypeScript", primary: 19, adopt: 5 },
    { name: "SQL", primary: 17, adopt: 4 },
  ];

  items.forEach((item, i) => {
    const baseY = 3.0 + i * 0.35;
    // Language name
    slide.addText(item.name, {
      x: 6.05, y: baseY, w: 1.1, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "left", valign: "middle"
    });
    // Primary bar background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.2, y: baseY + 0.03, w: 2.2, h: 0.12,
      fill: { color: "D4D4D4" }
    });
    // Primary bar fill
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.2, y: baseY + 0.03, w: 2.2 * (item.primary / 35), h: 0.12,
      fill: { color: theme.secondary }
    });
    // Adopt bar background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.2, y: baseY + 0.17, w: 2.2, h: 0.1,
      fill: { color: "E8E8E8" }
    });
    // Adopt bar fill
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.2, y: baseY + 0.17, w: 2.2 * (item.adopt / 35), h: 0.1,
      fill: { color: theme.accent }
    });
    // Values
    slide.addText(item.primary + "% / " + item.adopt + "%", {
      x: 9.0, y: baseY, w: 0.7, h: 0.3,
      fontSize: 8, fontFace: "Calibri",
      color: "64748B", align: "right", valign: "middle"
    });
  });

  // Legend for mini bars
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 4.75, w: 0.15, h: 0.1,
    fill: { color: theme.secondary }
  });
  slide.addText("Primary", {
    x: 7.4, y: 4.7, w: 0.7, h: 0.2,
    fontSize: 7, fontFace: "Calibri", color: "64748B", align: "left", valign: "middle"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.1, y: 4.75, w: 0.15, h: 0.1,
    fill: { color: theme.accent }
  });
  slide.addText("Adoption Intent", {
    x: 8.3, y: 4.7, w: 1.0, h: 0.2,
    fontSize: 7, fontFace: "Calibri", color: "64748B", align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

