const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 5,
  title: 'Each Language Owns a Domain: AI Belongs to Python, UI to TypeScript'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.3, y: 0.15, w: 9.4, h: 0.7,
    fontSize: 20, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    fit: "shrink"
  });

  // Domain data
  const domains = [
    { domain: "AI / Machine Learning", lang: "Python", share: "31%", barW: 0.93, langColor: "2a9d8f" },
    { domain: "Data Processing & Analytics", lang: "Python", share: "17%", barW: 0.51, langColor: "2a9d8f" },
    { domain: "User Interface", lang: "TypeScript", share: "62%", barW: 1.0, langColor: "e9c46a" },
    { domain: "APIs & Services", lang: "Java", share: "49%", barW: 0.79, langColor: "f4a261" },
    { domain: "Application Logic & Workflows", lang: "Java", share: "55%", barW: 0.89, langColor: "f4a261" },
    { domain: "System Tools & Components", lang: "C++", share: "27%", barW: 0.44, langColor: "e76f51" },
    { domain: "Integrating with APIs & Services", lang: "Python", share: "38%", barW: 0.61, langColor: "2a9d8f" },
  ];

  // Table with heatmap-style bars
  const hdrOpts = () => ({
    fill: { color: theme.primary }, color: "FFFFFF", bold: true,
    fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle", margin: [4, 6, 4, 6]
  });

  const tableData = [
    [
      { text: "Application Domain", options: { ...hdrOpts(), align: "left" } },
      { text: "Leading Language", options: hdrOpts() },
      { text: "Share", options: hdrOpts() },
      { text: "Dominance", options: hdrOpts() }
    ],
    ...domains.map((d, i) => {
      const isAlt = i % 2 === 1;
      const bgColor = isAlt ? "F0F4F5" : "FFFFFF";
      return [
        { text: d.domain, options: { fill: { color: bgColor }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle", margin: [4, 6, 4, 6] } },
        { text: d.lang, options: { fill: { color: d.langColor }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle", margin: [4, 6, 4, 6] } },
        { text: d.share, options: { fill: { color: bgColor }, color: theme.primary, bold: true, fontSize: 11, fontFace: "Calibri", align: "center", valign: "middle", margin: [4, 6, 4, 6] } },
        { text: "", options: { fill: { color: bgColor }, margin: [0, 0, 0, 0] } }
      ];
    })
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.0, w: 9.0, h: 3.5,
    border: { pt: 0.5, color: "D4D4D4" },
    colW: [2.8, 1.5, 0.8, 3.9],
    autoPage: false
  });

  // Add visual bars in the "Dominance" column
  domains.forEach((d, i) => {
    const rowY = 1.0 + 0.5 + i * 0.43;
    const barMaxW = 3.5;
    // Background bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.75, y: rowY + 0.08, w: barMaxW, h: 0.22,
      fill: { color: "E8E8E8" },
      rectRadius: 0.03
    });
    // Filled bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.75, y: rowY + 0.08, w: barMaxW * d.barW, h: 0.22,
      fill: { color: d.langColor, transparency: 30 },
      rectRadius: 0.03
    });
  });

  // Insight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 9.0, h: 0.5,
    fill: { color: theme.primary, transparency: 92 },
    rectRadius: 0.03
  });
  slide.addText("Language choice is driven by domain, not general preference — hiring and training should align with domain specialization.", {
    x: 0.7, y: 4.7, w: 8.6, h: 0.5,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Source
  slide.addText("Source: JetBrains State of Developer Ecosystem 2024", {
    x: 0.3, y: 5.15, w: 5.0, h: 0.3,
    fontSize: 8, fontFace: "Calibri",
    color: "999999", align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

