const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 6,
  title: 'What This Means for Your Technology Strategy in 2025'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.primary }
  });

  // Title
  slide.addText(slideConfig.title, {
    x: 0.3, y: 0.25, w: 9.4, h: 0.65,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    fit: "shrink"
  });

  // 5 strategic takeaways
  const takeaways = [
    { num: "1", text: "Invest in Python for AI/ML teams — it is the undisputed leader", accent: "2a9d8f" },
    { num: "2", text: "TypeScript is the future of frontend and full-stack", accent: "e9c46a" },
    { num: "3", text: "Rust and Go are the growth plays for infrastructure and systems", accent: "f4a261" },
    { num: "4", text: "PHP and Ruby hiring pools are shrinking — plan succession now", accent: "e76f51" },
    { num: "5", text: "Developer satisfaction correlates with type safety and modern tooling — factor this into retention strategy", accent: "264653" },
  ];

  takeaways.forEach((item, i) => {
    const baseY = 1.15 + i * 0.82;

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: baseY + 0.05, w: 0.45, h: 0.45,
      fill: { color: item.accent }
    });
    slide.addText(item.num, {
      x: 0.5, y: baseY + 0.05, w: 0.45, h: 0.45,
      fontSize: 16, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Text
    slide.addText(item.text, {
      x: 1.15, y: baseY, w: 8.5, h: 0.55,
      fontSize: 14, fontFace: "Calibri",
      color: theme.primary, align: "left", valign: "middle"
    });

    // Subtle separator line
    if (i < takeaways.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: 1.15, y: baseY + 0.65, w: 8.3, h: 0,
        line: { color: "D4D4D4", width: 0.5 }
      });
    }
  });

  // Bottom accent bar with tagline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.25, w: 10, h: 0.375,
    fill: { color: theme.primary }
  });
  slide.addText("Data-driven decisions for technology strategy and hiring priorities", {
    x: 0.5, y: 5.25, w: 6, h: 0.375,
    fontSize: 10, fontFace: "Calibri",
    color: theme.accent, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

