const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 2,
  title: 'Python Closes the Gap: 8 Years of Language Usage Shifts'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.3, y: 0.2, w: 9.4, h: 0.7,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    fit: "shrink"
  });

  // Line chart with 5 key languages
  const chartData = [
    { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
    { name: "Python", labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
    { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
    { name: "Java", labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
    { name: "PHP", labels: ["2017", "2020", "2022", "2024"], values: [30, 27, 20, 17] },
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.3, y: 1.0, w: 5.8, h: 3.8,
    lineSize: 2.5,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    legendColor: theme.primary,
    showTitle: false,
    catAxisLabelColor: "64748B",
    catAxisLabelFontSize: 9,
    valAxisLabelColor: "64748B",
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    chartColors: ["264653", "2a9d8f", "e9c46a", "f4a261", "e76f51"],
    valAxisMinVal: 0,
    valAxisMaxVal: 80,
    lineSmooth: false,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    plotArea: { fill: { color: "FFFFFF" } }
  });

  // Right side: compact data table for all 10 languages
  const hdrOpts = () => ({
    fill: { color: theme.primary }, color: "FFFFFF", bold: true,
    fontSize: 9, fontFace: "Calibri", align: "center", valign: "middle", margin: [2, 4, 2, 4]
  });
  const cellOpts = (isAlt) => ({
    fill: { color: isAlt ? "F0F4F5" : "FFFFFF" },
    color: theme.primary, fontSize: 9, fontFace: "Calibri",
    align: "center", valign: "middle", margin: [2, 4, 2, 4]
  });
  const nameOpts = (isAlt) => ({
    fill: { color: isAlt ? "F0F4F5" : "FFFFFF" },
    color: theme.primary, fontSize: 9, fontFace: "Calibri", bold: true,
    align: "left", valign: "middle", margin: [2, 4, 2, 4]
  });
  const trendOpts = (isAlt, trend) => {
    const trendColor = trend.includes("growth") || trend.includes("Growth") ? "2a9d8f" :
                       trend.includes("decline") || trend.includes("Decline") ? "e76f51" : "f4a261";
    return {
      fill: { color: isAlt ? "F0F4F5" : "FFFFFF" },
      color: trendColor, fontSize: 8, fontFace: "Calibri",
      align: "left", valign: "middle", margin: [2, 4, 2, 4]
    };
  };

  const languages = [
    { name: "JavaScript", v2024: "61%", trend: "Declining from peak" },
    { name: "Python", v2024: "57%", trend: "Steady growth" },
    { name: "HTML/CSS", v2024: "51%", trend: "Gradual decline" },
    { name: "SQL", v2024: "48%", trend: "Plateaued" },
    { name: "Java", v2024: "46%", trend: "Slow decline" },
    { name: "TypeScript", v2024: "37%", trend: "Strong growth" },
    { name: "Go", v2024: "18%", trend: "Plateaued" },
    { name: "PHP", v2024: "17%", trend: "Significant decline" },
    { name: "Kotlin", v2024: "14%", trend: "Plateaued" },
    { name: "Rust", v2024: "11%", trend: "Steady growth" },
  ];

  const tableData = [
    [
      { text: "Language", options: { ...hdrOpts(), align: "left" } },
      { text: "2024", options: hdrOpts() },
      { text: "Trend", options: { ...hdrOpts(), align: "left" } }
    ],
    ...languages.map((lang, i) => [
      { text: lang.name, options: nameOpts(i % 2 === 1) },
      { text: lang.v2024, options: cellOpts(i % 2 === 1) },
      { text: lang.trend, options: trendOpts(i % 2 === 1, lang.trend) }
    ])
  ];

  slide.addTable(tableData, {
    x: 6.3, y: 1.0, w: 3.4, h: 3.8,
    border: { pt: 0.5, color: "D4D4D4" },
    colW: [1.3, 0.6, 1.5],
    autoPage: false
  });

  // Insight callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 4.85, w: 3.4, h: 0.55,
    fill: { color: theme.accent, transparency: 85 },
    rectRadius: 0.03
  });
  slide.addText("Python rose from 32% to 57%; TypeScript tripled from 12% to 37%", {
    x: 6.4, y: 4.85, w: 3.2, h: 0.55,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Source
  slide.addText("Source: JetBrains State of Developer Ecosystem 2024", {
    x: 0.3, y: 5.15, w: 5.0, h: 0.3,
    fontSize: 8, fontFace: "Calibri",
    color: "999999", align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

