    fill: { color: isAlt ? "F0F4F5" : "FFFFFF" },
    color: theme.primary, fontSize: 9, fontFace: "Calibri",
    align: "center", valign: "middle", margin: [2, 4, 2, 4]
  });
  const nameOpts = (isAlt) => ({
    fill: { color: isAlt ? "F0F4F5" : "FFFFFF" },
    color: theme.primary, fontSize: 9, fontFace: "Calibri", bold: true,
    align: "left", valign: "middle", margin: [2, 4, 2, 4]
  });
